import {text,list,identifiers,choice} from '../creative-kit/state.js?v=0.21.0';
import {ancestry,blankAncestry,sourceSnapshot,derivedFrom,validateGraph,hasDescendants,ancestryMarkdown,assertPortable} from '../shared/ancestry.js?v=0.21.0';
import {MOMENT_FIELDS,IDEA_FIELDS,FITS,MOMENT_LABELS} from './definitions.js?v=0.21.0';
const clone=x=>structuredClone(x);
const meta=id=>({id,title:'Original scene',changed:'',reason:'',order:0,ancestry:blankAncestry()});
export function upgradeIdea(i){i.fit??='unchecked';i.fitReason??='';i.fitNeeds??='';i.checkedAgainst??=null;i.ancestry=ancestry(i.ancestry);i.changed??='';i.reason??='';return i;}
export function upgrade(w){w.scene??=meta('scene-original');w.variants??=[];w.compareSceneIds??=[w.scene.id];w.compareIdeaIds??=w.ideas.slice(0,4).map(i=>i.id);w.chosenTest??=null;w.decision??='';w.ideas.forEach(upgradeIdea);return w;}
export const currentScene=w=>({...clone(w.scene),moments:clone(w.moments),ideas:clone(w.ideas),selectedId:w.selectedId});
export const allScenes=w=>[currentScene(w),...w.variants].sort((a,b)=>a.order-b.order);
function load(w,s){w.scene=Object.fromEntries(['id','title','changed','reason','order','ancestry'].map(k=>[k,clone(s[k])]));w.moments=clone(s.moments);w.ideas=clone(s.ideas);w.selectedId=s.selectedId;}
export function sceneFields(w,s){return [{label:'Situation',text:w.problem},...s.moments.flatMap((m,i)=>MOMENT_FIELDS.map(k=>({label:`Moment ${i+1} · ${MOMENT_LABELS[k]}`,text:m[k]})))];}
export function sceneSnapshot(w,s){return sourceSnapshot(s.id,s.title,[{label:'Variation',text:s.changed},{label:'Reason',text:s.reason},...sceneFields(w,s)]);}
export function reviewSnapshot(w,s,i){return sourceSnapshot(`${s.id}--${i.id}`,i.title,[...sceneFields(w,s),{label:'Placement',text:i.momentId??'Unplaced'},...IDEA_FIELDS.map(k=>({label:k,text:i[k]}))]);}
export function ideaSnapshot(w,s,i){return sourceSnapshot(i.id,i.title,[...reviewSnapshot(w,s,i).fields,{label:'Fit',text:FITS[i.fit]},{label:'Fit reasoning',text:i.fitReason},{label:'Required adaptation',text:i.fitNeeds},{label:'Branch change',text:i.changed},{label:'Branch reason',text:i.reason}]);}
export function needsReview(w,s,i){return i.stale||!!i.checkedAgainst&&JSON.stringify(i.checkedAgainst.fields)!==JSON.stringify(reviewSnapshot(w,s,i).fields);}
export function validateVariants(w,validateScene){
 upgrade(w);list(w.variants,11);w.scene.ancestry=ancestry(w.scene.ancestry);for(const s of w.variants){s.ancestry=ancestry(s.ancestry);list(s.ideas,24);s.ideas.forEach(upgradeIdea);}const scenes=allScenes(w);identifiers(scenes);validateGraph(scenes);
 const orders=[];for(const s of scenes){for(const k of ['title','changed','reason'])text(s[k]);if(!Number.isInteger(s.order)||s.order<0)throw Error('Invalid scene order.');orders.push(s.order);ancestry(s.ancestry);validateScene(s);for(const i of s.ideas){upgradeIdea(i);choice(i.fit,Object.keys(FITS));for(const k of ['fitReason','fitNeeds','changed','reason'])text(i[k]);if(i.checkedAgainst!==null)ancestry(derivedFrom([i.checkedAgainst]));}validateGraph(s.ideas);}
 if(new Set(orders).size!==orders.length)throw Error('Scenes need distinct positions.');
 list(w.compareSceneIds,4);list(w.compareIdeaIds,4);if(new Set(w.compareSceneIds).size!==w.compareSceneIds.length||w.compareSceneIds.some(id=>!scenes.some(s=>s.id===id&&!s.ancestry.parked)))throw Error('Invalid scene comparison.');
 if(new Set(w.compareIdeaIds).size!==w.compareIdeaIds.length||w.compareIdeaIds.some(id=>!scenes.some(s=>s.ideas.some(i=>i.id===id))))throw Error('Invalid intervention comparison.');
 if(w.chosenTest!==null&&!scenes.some(s=>s.id===w.chosenTest.sceneId&&!s.ancestry.parked&&s.ideas.some(i=>i.id===w.chosenTest.ideaId&&!i.ancestry.parked)))throw Error('Chosen test is missing.');text(w.decision);assertPortable(w);
}
function repair(w){const scenes=allScenes(w);w.compareIdeaIds=w.compareIdeaIds.filter(id=>scenes.some(s=>s.ideas.some(i=>i.id===id)));if(w.chosenTest&&!scenes.some(s=>s.id===w.chosenTest.sceneId&&!s.ancestry.parked&&s.ideas.some(i=>i.id===w.chosenTest.ideaId&&!i.ancestry.parked)))w.chosenTest=null;}
export function applyVariant(w,a){
 const scenes=()=>allScenes(w), find=id=>id===w.scene.id?w:w.variants.find(s=>s.id===id), sceneMeta=id=>id===w.scene.id?w.scene:w.variants.find(s=>s.id===id);
 if(a.type==='scene-switch'){if(a.id===w.scene.id)return;const target=w.variants.find(s=>s.id===a.id);if(!target)throw Error('Scene not found.');const before=currentScene(w);w.variants=w.variants.filter(s=>s.id!==a.id);w.variants.push(before);load(w,target);}
 else if(a.type==='scene-branch'){
  if(scenes().length>=12||scenes().some(s=>s.id===a.id))throw Error('Use a new scene, up to 12 per workspace.');const original=currentScene(w),next=clone(original);next.id=a.id;next.title=text(a.title);if(!next.title.trim())throw Error('Name the scene variation.');next.changed=text(a.changed||'');next.reason=text(a.reason||'');next.order=Math.max(...scenes().map(s=>s.order))+1;next.ancestry=derivedFrom([sceneSnapshot(w,original)]);
  const m=next.moments.find(m=>m.id===a.momentId);if(a.changes&&Object.keys(a.changes).length){if(!m)throw Error('Choose a moment to vary.');for(const [k,v]of Object.entries(a.changes)){choice(k,MOMENT_FIELDS);m[k]=text(v);}}
  if(a.position!==undefined){if(!m||!Number.isInteger(a.position)||a.position<0||a.position>=next.moments.length)throw Error('Choose a position in the scene.');next.moments.splice(next.moments.findIndex(x=>x.id===m.id),1);next.moments.splice(a.position,0,m);}
  next.ideas.forEach(i=>i.stale=true);w.variants.push(original);load(w,next);if(w.compareSceneIds.length<4)w.compareSceneIds.push(next.id);
 }
 else if(a.type==='scene-edit'){choice(a.field,['title','changed','reason']);w.scene[a.field]=text(a.value);}
 else if(a.type==='scene-compare'){if(!sceneMeta(a.id)||sceneMeta(a.id).ancestry.parked)throw Error('Choose an active scene.');if(w.compareSceneIds.includes(a.id))w.compareSceneIds=w.compareSceneIds.filter(x=>x!==a.id);else{if(w.compareSceneIds.length>=4)throw Error('Compare up to four scenes.');w.compareSceneIds.push(a.id);}}
 else if(a.type==='scene-park'){const s=sceneMeta(a.id);if(!s)throw Error('Scene not found.');s.ancestry.parked=!s.ancestry.parked;if(s.ancestry.parked)w.compareSceneIds=w.compareSceneIds.filter(x=>x!==a.id);}
 else if(a.type==='scene-remove'){if(scenes().length<2)throw Error('Keep one scene.');if(!sceneMeta(a.id))throw Error('Scene not found.');if(hasDescendants(scenes(),a.id))throw Error('This scene has branches. Park it to keep their history.');if(a.id===w.scene.id){const target=w.variants[0];w.variants=w.variants.slice(1);load(w,target);}else w.variants=w.variants.filter(s=>s.id!==a.id);w.compareSceneIds=w.compareSceneIds.filter(x=>x!==a.id);}
 else if(a.type==='scene-copy-idea'){const i=w.ideas.find(i=>i.id===a.id),target=find(a.sceneId);if(!i||!target)throw Error('Choose an intervention and a scene.');if(target.ideas.some(x=>x.id===i.id))throw Error('This intervention already has a version in that scene. Open it to review.');if(target.ideas.length>=24)throw Error('Keep at most 24 interventions per scene.');const next=clone(i),snapshot=ideaSnapshot(w,currentScene(w),i);snapshot.id=`${w.scene.id}--${i.id}`;next.momentId=null;next.stale=true;next.fit='unchecked';next.fitReason='';next.fitNeeds='';next.checkedAgainst=null;next.ancestry=derivedFrom([snapshot]);target.ideas.push(next);}
 else if(a.type==='scene-idea-branch'){const i=w.ideas.find(i=>i.id===a.id);if(!i)throw Error('Intervention is missing.');if(w.ideas.some(i=>i.id===a.newId))throw Error('Choose a new intervention identifier.');w.ideas.push({...clone(i),id:a.newId,title:'Variation: '+i.title.slice(0,19989),changed:'',reason:'',fit:'unchecked',fitReason:'',fitNeeds:'',checkedAgainst:null,stale:true,ancestry:derivedFrom([ideaSnapshot(w,currentScene(w),i)])});if(w.compareIdeaIds.length<4)w.compareIdeaIds.push(a.newId);}
 else if(a.type==='scene-idea-compare'){if(!scenes().some(s=>s.ideas.some(i=>i.id===a.id)))throw Error('Intervention is missing.');if(w.compareIdeaIds.includes(a.id))w.compareIdeaIds=w.compareIdeaIds.filter(x=>x!==a.id);else{if(w.compareIdeaIds.length>=4)throw Error('Compare up to four interventions.');w.compareIdeaIds.push(a.id);}}
 else if(a.type==='scene-choose'){const s=find(a.sceneId),m=sceneMeta(a.sceneId),i=s?.ideas.find(i=>i.id===a.id);if(!i||m.ancestry.parked||i.ancestry.parked)throw Error('Choose an active intervention and scene.');w.chosenTest=w.chosenTest?.sceneId===a.sceneId&&w.chosenTest?.ideaId===a.id?null:{sceneId:a.sceneId,ideaId:a.id};}
 else if(a.type==='scene-decision')w.decision=text(a.value);
 else throw Error('Unknown scene variation action.');repair(w);
}
export function variantsMarkdown(w,sceneMarkdown){const out=['## Scene variations',w.decision?`Decision: ${w.decision}`:'Decision not recorded.'];for(const s of allScenes(w)){out.push(`### ${s.title}${s.id===w.scene.id?' · open scene':''}`,s.ancestry.parked?'Parked':'Active',`Changed: ${s.changed}`,`Reason: ${s.reason}`);if(s.id!==w.scene.id)out.push(sceneMarkdown({...s,problem:w.problem}));out.push(ancestryMarkdown(s.ancestry));for(const i of s.ideas){out.push(`#### Fit: ${i.title}`,`Placement: ${s.moments.find(m=>m.id===i.momentId)?.title||'Unplaced'}`,`${FITS[i.fit]}${needsReview(w,s,i)?' · scene or intervention changed; review needed':''}`,`Reason: ${i.fitReason}`,`Required adaptation: ${i.fitNeeds}`,`Intervention variation: ${i.changed}`,`Reason for variation: ${i.reason}`,w.chosenTest?.sceneId===s.id&&w.chosenTest?.ideaId===i.id?'Chosen test':'',ancestryMarkdown(i.ancestry));if(i.checkedAgainst)out.push('Last reviewed context',ancestryMarkdown(derivedFrom([i.checkedAgainst])));}}return out.filter(Boolean).join('\n\n');}
